#[test]
fn calculator_language_instantiates() {
    let lang = CalculatorLanguage;
    assert_eq!(lang.name(), "Calculator");
}

#[test]
fn calculator_metadata_populated() {
    let lang = CalculatorLanguage;
    let meta = lang.metadata();
    assert!(!meta.types().is_empty(), "language should have at least one type");
    assert!(!meta.terms().is_empty(), "language should have at least one term");
}

#[test]
fn unit_calculator_tern() {
    mettail_runtime::clear_var_cache();
    let term = Int::Tern(Box::new(Int::NumLit(0i32)), Box::new(Int::NumLit(0i32)), Box::new(Int::NumLit(0i32)));
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for Tern");
    if let Ok(parsed) = Int::parse(&displayed) {
        let re_displayed = format!("{}", parsed);
        assert_eq!(displayed, re_displayed,
            "Roundtrip failed for Tern: {} != {}", displayed, re_displayed);
    }
}

